void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create icon and bind it to the model
    UiImage* icon = ui_image_create();
    model_bind_string(model, element_binding->icon_property, icon->image_url);

    // Create content text and bind it to the model
    UiText* content_text = ui_text_create();
    model_bind_string(model, element_binding->content_property, content_text->text);

    // Create description text and bind it to the model
    UiText* description_text = ui_text_create();
    model_bind_string(model, element_binding->description_property, description_text->text);

    // Create layout to hold UI components
    UiLayout* layout = ui_layout_create(UI_LAYOUT_VERTICAL);
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content_text);
    ui_layout_add_child(layout, description_text);

    // Create a background button for click handling
    UiButton* background_button = ui_button_create();
    ui_button_set_layout(background_button, layout);

    // Bind button colors to the model
    model_bind_color(model, element_binding->background_color_property, background_button->background_color);

    // Set the click handler to trigger navigation
    ui_button_set_on_click(background_button, (UiOnClickHandler)ui_browser_interface_navigate, browser);

    // Add the constructed UI element to the scene
    ui_scene_add_element(scene, (UiElement*)background_button);
}

void add_suggestion_to_scene(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create UI components
    UiElement* icon = ui_icon_create("suggestion_icon");
    UiElement* content = ui_text_create("suggestion_content");
    UiElement* description = ui_text_create("suggestion_description");
    UiElement* layout = ui_layout_create(UI_LAYOUT_VERTICAL);

    // Bind UI elements to model
    model_bind(icon, model, "icon_property", element_binding);
    model_bind(content, model, "content_property", element_binding);
    model_bind(description, model, "description_property", element_binding);

    // Create background button with navigation action
    UiElement* background_button = ui_button_create("suggestion_background");
    ui_button_set_action(background_button, (UiActionCallback)ui_browser_navigate, browser);

    // Bind button colors to model
    model_bind_color(background_button, model, "background_color_property");

    // Add components to layout
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content);
    ui_layout_add_child(layout, description);

    // Add layout to background button
    ui_element_add_child(background_button, layout);

    // Add final element to scene
    ui_scene_add_element(scene, background_button);
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create and bind icon element
    UiElement* icon = ui_element_create(UI_ELEMENT_ICON);
    model_bind_property(model, "icon", icon, "image");

    // Create and bind content text element
    UiElement* content_text = ui_element_create(UI_ELEMENT_TEXT);
    model_bind_property(model, "content", content_text, "text");

    // Create and bind description text element
    UiElement* description_text = ui_element_create(UI_ELEMENT_TEXT);
    model_bind_property(model, "description", description_text, "text");

    // Create a layout to hold the UI components
    UiElement* layout = ui_element_create(UI_ELEMENT_LAYOUT);
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content_text);
    ui_layout_add_child(layout, description_text);

    // Create background button for click interaction
    UiElement* background_button = ui_element_create(UI_ELEMENT_BUTTON);
    model_bind_property(model, "background_color", background_button, "color");

    // Set navigation action on click
    ui_element_set_callback(background_button, UI_EVENT_CLICK, (UiCallback) ui_browser_interface_navigate, browser);

    // Add the background button to the layout
    ui_layout_add_child(layout, background_button);

    // Add the complete UI element to the scene
    ui_scene_add_element(scene, layout);
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create icon element and bind it to the model
    UiElement* icon = create_icon_element();
    bind_icon(icon, model, "icon_property");

    // Create content text element and bind it to the model
    UiElement* content_text = create_text_element();
    bind_text(content_text, model, "content_property");

    // Create description text element and bind it to the model
    UiElement* description_text = create_text_element();
    bind_text(description_text, model, "description_property");

    // Create a layout to hold the icon, content, and description
    UiElement* layout = create_vertical_layout();
    add_child(layout, icon);
    add_child(layout, content_text);
    add_child(layout, description_text);

    // Create a background button that triggers navigation on click
    UiElement* background_button = create_button_element();
    set_on_click(background_button, (void*)browser, navigate_to_suggestion);

    // Bind button's color to the model
    bind_color(background_button, model, "button_color_property");

    // Add the layout to the button
    set_content(background_button, layout);

    // Bind the button to the suggestion binding object for UI updates
    bind_element_to_model(background_button, element_binding);

    // Add the constructed UI element to the scene
    add_element_to_scene(scene, background_button);
}
